# 메뉴판(메뉴 → 가격)을 만들고 주문 합계를 구해요.
n = int(input())
prices = {}
for _ in range(n):
    menu, price = input().split()
    prices[menu] = int(price)

orders = input().split()
total = 0
for menu in orders:
    # 메뉴판에 없는 이름을 꺼내면 오류가 나니, 있는지 먼저 확인해요.
    if menu in prices:
        total += prices[menu]
print(total)
